package io.forgeloop.control.application;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*; import io.forgeloop.control.domain.*; import java.util.*; import org.junit.jupiter.api.Test;
class RunnerServiceTest { RunnerRepository runners=mock(RunnerRepository.class); RunnerRegistrationTokenRepository tokens=mock(RunnerRegistrationTokenRepository.class); RunnerService service=new RunnerService(runners,tokens); @Test void issuesAOneTimeEnrollmentCredential() throws Exception {when(tokens.save(any())).thenAnswer(call->call.getArgument(0));String raw=service.issueRegistrationToken("org-1");RunnerRegistrationToken token=new RunnerRegistrationToken(java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8))),"org-1",java.time.Instant.now().plusSeconds(60));when(tokens.findByTokenHash(any())).thenReturn(Optional.of(token));when(runners.save(any())).thenAnswer(call->call.getArgument(0));RunnerEnrollment enrollment=service.register(new RunnerRegistration(raw,"build-node","0.1.0",List.of("docker","git")));assertEquals("org-1",enrollment.runner().getOrganizationId());assertEquals(64,enrollment.credential().length());assertThrows(IllegalStateException.class,()->service.register(new RunnerRegistration(raw,"other","0.1.0",List.of("git"))));} @Test void rejectsHeartbeatWithWrongRunnerCredential() throws Exception {Runner runner=new Runner("org","node","1",List.of("git"),java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest("valid".getBytes(java.nio.charset.StandardCharsets.UTF_8))));when(runners.findById("runner")).thenReturn(Optional.of(runner));assertThrows(IllegalArgumentException.class,()->service.heartbeat("runner","wrong"));} }
